@Composable
fun AddChainStepDialog(
    parentTitle: String,
    onDismiss: () -> Unit,
    onAdd: (String, Difficulty) -> Unit
) {
    var stepTitle by remember { mutableStateOf("") }
    var stepDifficulty by remember { mutableStateOf(Difficulty.PEON) }

    GoblinAlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Text(stringResource(R.string.stack_onto_title, parentTitle), fontWeight = FontWeight.ExtraBold, color = MaterialTheme.colorScheme.primary, fontSize = 16.sp)
        },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                Text(stringResource(R.string.add_next_step_description), fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f))

                OutlinedTextField(
                    value = stepTitle,
                    onValueChange = { stepTitle = it },
                    placeholder = { Text(stringResource(R.string.next_step_placeholder)) },
                    modifier = Modifier.fillMaxWidth().testTag("chain_step_input"),
                    singleLine = true
                )

                Text(stringResource(R.string.difficulty_label), style = MaterialTheme.typography.bodySmall, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f))

                DifficultySelector(selectedDifficulty = stepDifficulty, onSelect = { stepDifficulty = it })
            }
        },
        confirmButton = {
            Button(
                onClick = { if (stepTitle.isNotBlank()) onAdd(stepTitle.trim(), stepDifficulty) },
                enabled = stepTitle.isNotBlank(),
                modifier = Modifier.testTag("add_chain_step_button")
            ) {
                Text(stringResource(R.string.stack_it_button), fontWeight = FontWeight.Bold)
            }
        },
        dismissButton = { TextButton(onClick = onDismiss) { Text(stringResource(R.string.action_cancel)) } }
    )
}
